with q as (
 select * from (values
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-eligibility-01','Decreto nº 8.912/2018 — condições para concorrer','De acordo com o art. 3º do Decreto nº 8.912/2018, qual situação impede o servidor de concorrer à promoção?','(A) Ter concluído 120 horas de capacitação.\n(B) Ter sofrido penalidade disciplinar nos 12 meses anteriores à promoção.\n(C) Estar na classe imediatamente anterior à pretendida.\n(D) Ter obtido avaliação de 90 pontos.\n(E) Ter participado de curso a distância.','B','O art. 3º, V, exige que o servidor não tenha sofrido penalidade disciplinar nos 12 meses anteriores à promoção. As condições são cumulativas, ressalvadas apenas as exceções expressas do parágrafo único.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-commission-02','Decreto nº 8.912/2018 — comissão de recurso','Qual composição diferencia a Comissão Permanente de Recurso da Comissão Permanente de Promoção?','(A) Apenas servidores do setor de pessoal.\n(B) Presidente, dois servidores, assistente social e psicólogo, com respectivos suplentes.\n(C) Somente Delegados de Polícia.\n(D) Presidente e três servidores, sem suplentes.\n(E) Um servidor e um representante sindical.','B','O art. 9º, § 3º, prevê presidente e suplente, dois servidores e suplentes, assistente social e suplente e psicólogo e suplente.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-appeal-03','Decreto nº 8.912/2018 — prazo recursal','Segundo os arts. 15 a 17 do Decreto nº 8.912/2018, qual é o prazo indicado para o servidor recorrer do resultado final da promoção?','(A) 5 dias.\n(B) 7 dias.\n(C) 10 dias.\n(D) Até 15 dias.\n(E) 30 dias.','D','Os arts. 15, parágrafo único, e 17, VII, indicam prazo de até 15 dias, embora descrevam marcos de contagem com redações diferentes. A questão literal deve observar o dispositivo citado.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-factors-04','Decreto nº 8.912/2018 — fatores de promoção','Qual alternativa apresenta somente fatores expressamente enumerados no art. 20 do Decreto nº 8.912/2018?','(A) Antiguidade, escolaridade, produtividade e disciplina.\n(B) Competência técnica, eficiência, relacionamento interpessoal e conduta ético-funcional.\n(C) Idade, tempo de serviço, títulos e lotação.\n(D) Hierarquia, produtividade financeira, iniciativa e renda.\n(E) Assiduidade, titulação, tempo de serviço e residência.','B','O art. 20 inclui competência técnica, eficiência, relacionamento interpessoal, conduta ético-funcional, capacidade de iniciativa, zelo, pontualidade e assiduidade.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
)
